import os
import base64
import json

def restore_file(dest, b64_data):
    os.makedirs(os.path.dirname(dest), exist_ok=True)
    with open(dest, "wb") as f:
        f.write(base64.b64decode(b64_data))

print("Restoring stripped RGB/RGBA images from base64...")
restore_file("MellClicker/Resources/Assets.xcassets/AppIcon.appiconset/icon_1024x1024@1x.png", "")
restore_file("MellClicker/Resources/Assets.xcassets/MellButton.imageset/MellButton.png", "")
restore_file("MellClicker/Resources/Assets.xcassets/MellButton.imageset/MellButton@2x.png", "")
restore_file("MellClicker/Resources/Assets.xcassets/MellButton.imageset/MellButton@3x.png", "")

print("Writing Single-Size AppIcon Contents.json...")
appicon_json = {
  "images" : [
    {
      "filename" : "icon_1024x1024@1x.png",
      "idiom" : "universal",
      "platform" : "ios",
      "size" : "1024x1024"
    }
  ],
  "info" : {
    "author" : "xcode",
    "version" : 1
  }
}

with open("MellClicker/Resources/Assets.xcassets/AppIcon.appiconset/Contents.json", "w") as f:
    json.dump(appicon_json, f, indent=2)

print("Restoration complete!")
